for w in CartesianProduct({0,1,2,3}, repeat=10):
    palettes = [set(w[e] for e in edges(t))
                for t in increasing_triples(5)]
    if number_of_distinct(palettes) == 10:
        return w
return NO_WITNESS

check(prefix):
    if any newly completed pair has equal codes:
        return true
    if length(prefix) == 10:
        return false
    return AND(check(prefix + [q]) for q in {0,1,2,3})
